private def poll(timeout: Duration)(cond: => Boolean < Sync)(using Frame): Boolean < Async =
  Clock.let(Clock.live)(Clock.deadline(timeout).map { d =>
    Loop.foreach(cond.map {
      case true  => Loop.done(true)
      case false => d.isOverdue.map(late => if late then Loop.done(false) else Async.sleep(5.millis).andThen(Loop.continue))
    })
  })
