private def cells(row: String, x: Int, width: Int): String =
  val (_, parts) = TextEdit.graphemes(row).foldLeft((0, Vector.empty[String])) { case ((col, acc), g) =>
    val w = Layout.textWidth(g).max(1)
    val part =
      if col >= x && col + w <= x + width then g
      else if col < x + width && col + w > x then " " * ((col + w).min(x + width) - col.max(x))
      else ""
    (col + w, acc :+ part) }
  trimEnd(parts.mkString)

